using System.IO; using UnityEngine; using UnityEngine.UIElements;
public sealed class ImageWidget:IRuntimeWidget {
 readonly VisualElement root; public VisualElement Root=>root;
 public ImageWidget(WidgetDefinition d,WidgetContext c){root=new VisualElement();root.AddToClassList("image-widget");string asset=d.PropString("asset");if(c==null||string.IsNullOrWhiteSpace(c.AddonRootPath)||string.IsNullOrWhiteSpace(asset)){Debug.LogWarning("ImageWidget has no valid addon root/asset path.");return;}string path=Path.Combine(c.AddonRootPath,asset.Replace('/',Path.DirectorySeparatorChar));if(!File.Exists(path)){Debug.LogWarning("Addon image asset not found: "+path);return;}byte[] bytes=File.ReadAllBytes(path);var tex=new Texture2D(2,2,TextureFormat.RGBA32,false);if(!tex.LoadImage(bytes)){Debug.LogWarning("Could not decode addon image asset: "+path);Object.Destroy(tex);return;}tex.name=Path.GetFileNameWithoutExtension(path);var image=new Image{image=tex};image.AddToClassList("image-widget-image");switch(d.PropString("scaleMode").ToLowerInvariant()){case"stretch":image.scaleMode=ScaleMode.StretchToFill;break;case"crop":image.scaleMode=ScaleMode.ScaleAndCrop;break;default:image.scaleMode=ScaleMode.ScaleToFit;break;}image.style.flexGrow=1;root.Add(image);}
 public void Refresh(){}
}
